/**
 * Picture precedence shared by event cards and the detail page's og:image.
 *
 * A picture the organizer uploaded wins over the autogenerated social preview
 * (`DEM/demo_preview-N.jpg`, or the legacy `/static/demo_preview/`). Older
 * events also carry a generated preview as their cover_picture, copied there
 * when they had no picture, so those URLs never count as uploads. The Go card
 * endpoints apply the same rule in `cardImage`.
 */
export function isGeneratedPreview(url: unknown): boolean {
  return typeof url === 'string' && /\/demo_preview[-/]/.test(url);
}

type ImageFields = {
  gallery_images?: unknown; images?: unknown; img?: unknown;
  cover_picture?: unknown; cover_image?: unknown; preview_image?: unknown;
};

function urls(value: unknown): string[] {
  const list = Array.isArray(value) ? value : [value];
  return list.flatMap(item => typeof item === 'string' ? item.split('\n') : [])
    .map(item => item.trim()).filter(Boolean);
}

/** The first uploaded picture, or null when the event has none. */
export function uploadedImage(event: ImageFields): string | null {
  for (const field of [event.gallery_images, event.images, event.img, event.cover_picture, event.cover_image]) {
    const found = urls(field).find(url => !isGeneratedPreview(url));
    if (found) return found;
  }
  return null;
}

/** Every candidate in display order: uploads, then the current preview, then the rest. */
export function imageCandidates(event: ImageFields): string[] {
  const uploaded = [event.gallery_images, event.images, event.img, event.cover_picture, event.cover_image]
    .flatMap(urls).filter(url => !isGeneratedPreview(url));
  const rest = [event.preview_image, event.cover_image, event.cover_picture, event.img].flatMap(urls);
  return [...new Set([...uploaded, ...rest])];
}
